mapper.select:
SELECT id, activity_id, award_id, award_count, award_rate, award_surplus_count, create_time, update_time
FROM activity_prize
WHERE activity_id = #{activityId}

mapper.update:
UPDATE activity_prize
SET award_surplus_count = award_surplus_count - 1
WHERE activity_id = #{activityId}
  AND award_id = #{awardId}
  AND award_surplus_count > 0
